"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[83866],{83866:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/jack-of-white-silver.png\\"\\n          title=\\"Snowboard Jack\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"CL Books\\"\\n          publishedDate=\\"2016-08-30\\"\\n          isbn=\\"9788997722396\\"\\n          rating=3\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\nThis is the first work in the ```Snow Mountain series```, deeply reflecting the personal taste of the author, who is known as a snowboarding enthusiast.  \\n<br>\\nThe vast snowy field forms a closed space that naturally blocks the intervention of the outside world, especially public power like the police.  \\nGeographical isolation provides an environmental basis for covering up cases and creates a limitation where one must face threats only with internal figures.  \\n<br> \\nThere is some disappointment in the work due to the somewhat clich\xe9d theme of corporate greed, system absurdity, and individual conscience against it, as well as repetitive blackmail patterns.  \\n<br>\\nThe absence of <mark>poetic justice</mark> rather seems to realistically show how those with huge capital and power in the real world cleverly escape the law and evade responsibility.  "}')}}]);